import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, RepeatWrapping } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = items[0] ?? { text: 'Features 3', typography: { fontSize: 39 } };

  const root = new Group();
  root.name = 'hub-features-card-0-label';

  const wrapper = new Group();
  wrapper.name = 'label-wrapper';
  root.add(wrapper);

  // --- atlas region aspect ---
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const plateHeight = 0.42;
  const plateWidth = plateHeight * aspect;

  // --- colors as vec3 nodes ---
  const inkC = new Color(colors.ink || '#16161d');
  const surfaceC = new Color(colors.surface || '#0b0b10');
  const accentC = colors.accent || '#ff2a38';
  const paperC = colors.paper || '#e8ecf2';

  const inkVec = vec3(inkC.r, inkC.g, inkC.b);
  const surfVec = vec3(surfaceC.r, surfaceC.g, surfaceC.b);
  const gradientNode = mix(surfVec, inkVec, uv().y);

  // --- backdrop plate: engineered gradient + subtle grain ---
  const plateGeo = new PlaneGeometry(plateWidth, plateHeight);
  const plateMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  plateMat.colorNode = gradientNode;
  plateMat.opacity = 0.96;

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.z = 0;
  wrapper.add(plate);

  let grainTexRef = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = RepeatWrapping;
      grainTexRef = tex;
      const grainNode = texture(tex).r.mul(0.15).add(0.85);
      plateMat.colorNode = gradientNode.mul(grainNode);
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- accent edge strip (signal red), thin, <=10% of frame area ---
  const stripWidth = Math.min(0.05, plateWidth * 0.06);
  const stripGeo = new PlaneGeometry(stripWidth, plateHeight * 0.86);
  const stripMat = new MeshBasicNodeMaterial({ transparent: true });
  const accentColorObj = new Color(accentC);
  stripMat.colorNode = vec3(accentColorObj.r, accentColorObj.g, accentColorObj.b);
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(-plateWidth / 2 + stripWidth / 2 + 0.02, 0, 0.001);
  wrapper.add(strip);

  // --- caption label text (verbatim copy from spec) ---
  const fontSize = labelItem.typography?.fontSize ?? 24;
  const textNode = ctx.fontAtlas.createText(labelItem.text ?? 'Features 3', {
    fontSize,
    color: paperC,
    align: 'left',
    letterSpacingPx: 2,
  });
  textNode.position.set(-plateWidth / 2 + stripWidth + 0.08, -0.02, 0.002);
  wrapper.add(textNode);

  // --- weighted entrance motion on inner wrapper only (root keeps scenePosition) ---
  const tl = gsap.timeline();
  wrapper.position.y = 0.2;
  wrapper.scale.setScalar(0.98);
  tl.to(wrapper.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(wrapper.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.05);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    plateGeo.dispose();
    plateMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    if (grainTexRef && grainTexRef.dispose) grainTexRef.dispose();
    if (textNode?.geometry) textNode.geometry.dispose?.();
    if (textNode?.material) textNode.material.dispose?.();
  };

  return root;
}
